export function createI18n(storage = null) {
  let locale = DEFAULT_LOCALE;
  try {
    const saved = storage?.getItem(LOCALE_STORAGE_KEY);
    if (SUPPORTED_LOCALES.includes(saved)) locale = saved;
  } catch { /* Private browsing can block storage. English still works. */ }

  const api = {
    get locale() { return locale; },
    setLocale(value) {
      if (!SUPPORTED_LOCALES.includes(value)) return false;
      locale = value;
      try { storage?.setItem(LOCALE_STORAGE_KEY, locale); } catch { /* Session-only preference. */ }
      return true;
    },
    t(key, params = {}) {
      const message = MESSAGES[key]?.[locale === 'zh-CN' ? 1 : 0] ?? key;
      return message.replace(/\{(\w+)\}/g, (match, name) =>
        Object.hasOwn(params, name) ? String(api.text(params[name])) : match);
    },
    text(value) {
      return value && typeof value === 'object' && value.key
        ? api.t(value.key, value.params) : value;
    },
    number(value) { return new Intl.NumberFormat(locale).format(value); },
  };
  return api;
}
